{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Push for a materially higher general cap"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek no de minimis or a lower one, and a tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer period—commonly at least 2–3 years"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Capacity and title should not be subject to the general warranty cap or short general limitation period."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "preserve agreed exceptions (including fraud, deliberate concealment and other negotiated carve-outs)"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket disclosure of the entire data room, accounts, registers and public records."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject the blanket bar on claims for anything known by the Buyer or its advisers"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make Completion conditional on an effective written consent and satisfaction or waiver"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require repayment and discharge at or before Completion, with lender payout and release evidence as a Completion deliverable."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Do not allow them to be silently treated as the Buyer’s ordinary post-Completion cost."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Require verified payment and an effective written assignment or other confirmation of the Company’s ownership/right to use the materials as a Completion condition."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Obtain an incident-specific indemnity for pre-Completion events"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Require accurate warranty disclosure and include any pre-Completion accrued or unavoidable commitments in the price/debt-like mechanics as appropriate."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reject the Seller’s default that every limitation applies to every claim unless expressly stated otherwise."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is only a share-register record; it is not a substitute for verification of title, encumbrances or transfer authority."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Tax and IP warranties should not simply be swept into the general regime."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

